/**
 * Route adapter for /learn/:native/:target — the link contract generated by
 * the inkwash homepage's language selector ("I SPEAK" / "I WANT TO LEARN").
 *
 * Maps the flat pair-slug URL to the nearest existing routed surface so every
 * homepage selector combination resolves without a 404.
 *
 * English target       → /learn/:native/english (handled by EnglishLearnRedirect)
 * Tutor-supported      → /ai-tutor?native=<slug>&target=<code>
 * Other-with-page      → /languages/<target>
 * Unsupported          → /languages (graceful fallback)
 */

import { Navigate, useParams } from "react-router-dom";

/** Target-language slugs that have a dedicated /languages/<slug> page but
 *  are NOT in the AI Tutor's language registry. For these we redirect to
 *  the language-lessons page instead of the AI Tutor. */
const PAGE_ONLY_TARGETS = new Set([
  "indonesian",
  "portuguese",
  "arabic",
  "hindi",
  "urdu",
  "punjabi",
  "italian",
  "swahili",
  "thai",
]);

/** Target-language slugs supported by the AI Tutor engine. */
const TUTOR_TARGETS: Record<string, string> = {
  english: "en",
  french: "fr",
  chinese: "zh",
  german: "de",
  japanese: "ja",
  korean: "ko",
  spanish: "es",
  vietnamese: "vi",
  turkish: "tr",
  russian: "ru",
};

export default function LearnPairRedirectPage() {
  const { native, target } = useParams<{ native?: string; target?: string }>();

  const t = (target ?? "").toLowerCase();
  const n = (native ?? "").toLowerCase();

  // English is handled by the dedicated /learn/:native/english route
  // (EnglishLearnRedirect in AppRouter.tsx). This case should not be
  // reached because that route is defined before this one, but guard
  // defensively.
  if (t === "english") return <Navigate to="/" replace />;

  // AI Tutor supports 10 target languages. Route there with native+target
  // query params so the tutor shows the correct pair-aware copy.
  const tutorCode = TUTOR_TARGETS[t];
  if (tutorCode) {
    return <Navigate to={`/ai-tutor?native=${encodeURIComponent(n)}&target=${encodeURIComponent(tutorCode)}`} replace />;
  }

  // Has a /languages/<target> page but no tutor support → show the
  // language-lessons page (grammar tables, vocab, etc.).
  if (PAGE_ONLY_TARGETS.has(t)) return <Navigate to={`/languages/${t}`} replace />;

  // Truly unsupported → graceful fallback to the languages index.
  return <Navigate to="/languages" replace />;
}
